/* AG CRM V92 — prévia fiel e autossuficiente do AG_SITE_v58 enviado pelo usuário.
   CSS, JS, logo e imagem principal ficam incorporados no srcdoc; os dados vêm do CRM atual. */
(function(){
  const b64="";
  let template='';
  window.AG_SITE_PREVIEW_HTML_V92=function(catalog){
    try{
      if(!template){
        const bin=atob(b64);
        const bytes=new Uint8Array(bin.length);
        for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
        template=new TextDecoder('utf-8').decode(bytes);
      }
      const safeJson=JSON.stringify(catalog||{version:1,settings:{brand:'AG'},properties:[]})
        .replace(/&/g,'\\u0026').replace(/</g,'\\u003c').replace(/>/g,'\\u003e')
        .replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
      return template.replace('__AG_PREVIEW_CATALOG_JSON__',safeJson);
    }catch(err){console.error('Falha ao montar prévia fiel do site AG',err);return '';}
  };
})();
